import { useEffect, useMemo, useState } from "react"
import {
  CloudOffIcon,
  HistoryIcon,
  MessageSquareIcon,
  PauseIcon,
  PencilLineIcon,
  PlayIcon,
  Share2Icon,
} from "lucide-react"

import { useCollection } from "@/lib/mini/store"
import { Button } from "@/components/ui/button"

import { EventTimeline } from "./event-timeline"
import type { TimelineEntry, TimelineType } from "./types"

type Preview = "live" | "empty" | "loading" | "error"

const PREVIEWS: Preview[] = ["live", "empty", "loading", "error"]

const TYPES: Record<string, TimelineType> = {
  edit: { label: "Edits", icon: PencilLineIcon, tone: 1 },
  comment: { label: "Comments", icon: MessageSquareIcon, tone: 2 },
  share: { label: "Sharing", icon: Share2Icon, tone: 3 },
  restore: { label: "Restores", icon: HistoryIcon, tone: 4 },
  sync: { label: "Sync", icon: CloudOffIcon, tone: 5 },
}

const DAY = Date.UTC(2026, 9, 19)
const at = (h: number, m: number, s: number) => DAY + ((h * 60 + m) * 60 + s) * 1000

const SEED: TimelineEntry[] = [
  { id: "ev-01", time: at(14, 2, 10), type: "edit", category: "Edit", level: "info", message: "Created the document from the trip template", detail: "Autumn trip itinerary" },
  { id: "ev-02", time: at(14, 6, 41), type: "edit", category: "Edit", level: "info", message: "Added the Day 1 schedule", detail: "Section: Day 1" },
  { id: "ev-03", time: at(14, 14, 3), type: "edit", category: "Edit", level: "info", message: "Pasted the train times for Day 2", detail: "Section: Day 2" },
  { id: "ev-04", time: at(14, 21, 37), type: "comment", category: "Comment", level: "info", message: "Joss: Is the 08:40 train too early for the group?", detail: "Thread on Day 2" },
  { id: "ev-05", time: at(14, 25, 12), type: "share", category: "Share", level: "info", message: "Shared with Joss as an editor" },
  { id: "ev-06", time: at(14, 33, 50), type: "edit", category: "Edit", level: "info", message: "Rewrote the packing list", detail: "Section: Packing" },
  { id: "ev-07", time: at(14, 41, 29), type: "sync", category: "Sync", level: "warning", message: "Autosave retried twice before it went through" },
  { id: "ev-08", time: at(14, 47, 5), type: "edit", category: "Edit", level: "info", message: "Moved the lunch stop from Day 2 to Day 3", detail: "Sections: Day 2, Day 3" },
  { id: "ev-09", time: at(14, 47, 5), type: "comment", category: "Comment", level: "info", message: "Mira: Moved. Day 2 now starts at 09:15.", detail: "Thread on Day 2" },
  { id: "ev-10", time: at(15, 1, 44), type: "edit", category: "Edit", level: "info", message: "Changed the hotel check-in time to 15:00", detail: "Section: Hotel" },
  { id: "ev-11", time: at(15, 9, 30), type: "restore", category: "Restore", level: "info", message: "Restored the 14:33 version of the packing list", detail: "Section: Packing" },
  { id: "ev-12", time: at(15, 12, 2), type: "edit", category: "Edit", level: "info", message: "Deleted the Spare ideas section" },
  { id: "ev-13", time: at(15, 18, 47), type: "edit", category: "Edit", level: "info", message: "Retyped the Day 3 route, including the long note about the harbour walk that nobody will read in full but that has to wrap onto several lines in a narrow window so the layout can be checked against it", detail: "Section: Day 3 / Route / Harbour walk" },
  { id: "ev-14", time: at(15, 21, 9), type: "sync", category: "Sync", level: "error", message: "Autosave could not reach the server", detail: "Edits after 15:18:47 are only on this device", isError: true },
  { id: "ev-15", time: at(15, 23, 20), type: "sync", category: "Sync", level: "info", message: "Back online, 1 pending edit saved" },
]

const timeFormat = new Intl.DateTimeFormat("en", {
  month: "short",
  day: "numeric",
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hourCycle: "h23",
  timeZone: "UTC",
})

const formatTime = (time: number) => timeFormat.format(time)

const HINTS = [
  "Click a time to seek",
  "/ search",
  "o switch order",
  "p jump to the playhead",
  "Esc clear search, then leave it",
  "Scroll the divider away and the list stops following",
]

export default function Demo() {
  const history = useCollection<TimelineEntry>("event-timeline-demo", SEED)
  const [preview, setPreview] = useState<Preview>("live")
  const [replay, setReplay] = useState(true)
  const [playhead, setPlayhead] = useState(at(15, 0, 0))
  const [playing, setPlaying] = useState(false)

  const times = useMemo(() => history.items.map((entry) => entry.time).sort((a, b) => a - b), [history.items])
  const first = times[0]
  const last = times.at(-1)
  const spanKnown = first !== undefined && last !== undefined && first < last
  const clamped = spanKnown ? Math.min(Math.max(playhead, first), last) : playhead
  const running = playing && spanKnown && clamped < last

  useEffect(() => {
    if (!running) return
    const id = window.setInterval(() => {
      setPlayhead((current) => times.find((time) => time > current) ?? current)
    }, 1000)
    return () => window.clearInterval(id)
  }, [running, times])

  const restoreSamples = () => {
    setPreview("live")
    void history.replaceAll(SEED)
  }

  const status = preview === "live" ? history.status : preview === "empty" ? "ready" : preview
  const entries = preview === "empty" ? [] : history.items

  const seek = (time: number) => {
    setPlaying(false)
    setPlayhead(time)
  }

  return (
    <div className="flex h-full min-h-0 flex-col gap-3 p-4">
      <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
        <div className="flex items-center gap-2">
          <span className="text-xs whitespace-nowrap text-muted-foreground">State preview (demo only)</span>
          <div role="group" aria-label="State preview" className="flex gap-1">
            {PREVIEWS.map((name) => (
              <Button
                key={name}
                size="xs"
                variant={preview === name ? "default" : "outline"}
                aria-pressed={preview === name}
                onClick={() => setPreview(name)}
                className="capitalize"
              >
                {name}
              </Button>
            ))}
          </div>
        </div>
        <div className="flex min-w-0 flex-wrap items-center gap-2">
          <span className="text-xs whitespace-nowrap text-muted-foreground">Replay (demo only)</span>
          <Button
            size="xs"
            variant={replay ? "default" : "outline"}
            aria-pressed={replay}
            onClick={() => {
              setReplay(!replay)
              setPlaying(false)
            }}
          >
            Playhead {replay ? "on" : "off"}
          </Button>
          <Button
            size="icon-xs"
            variant="outline"
            disabled={!replay || !spanKnown}
            aria-label={running ? "Pause replay" : "Play replay"}
            onClick={() => {
              if (clamped >= (last ?? 0)) setPlayhead(first ?? playhead)
              setPlaying(!running)
            }}
          >
            {running ? <PauseIcon aria-hidden /> : <PlayIcon aria-hidden />}
          </Button>
          <input
            type="range"
            aria-label="Playhead position"
            disabled={!replay || !spanKnown}
            min={first ?? 0}
            max={last ?? 0}
            step={1000}
            value={clamped}
            onChange={(event) => seek(Number(event.target.value))}
            className="w-40 accent-primary"
          />
          <span className="text-xs whitespace-nowrap text-muted-foreground tabular-nums">
            {replay && spanKnown ? formatTime(clamped) : "off"}
          </span>
        </div>
      </div>

      <div className="min-h-[24rem] flex-1 overflow-hidden rounded-lg border">
        <EventTimeline
          aria-label="Document edit history"
          entries={entries}
          status={status}
          error={new Error("Could not read the edit history (simulated).")}
          onRetry={() => setPreview("live")}
          types={TYPES}
          playhead={replay && spanKnown ? clamped : undefined}
          onSeek={seek}
          formatTime={formatTime}
          errorLabel="Save failed"
          emptyTitle="No edits recorded yet"
          emptyAction={{ label: "Restore sample history", onClick: restoreSamples }}
        />
      </div>

      <p className="text-xs text-muted-foreground">{HINTS.join(" · ")}</p>
    </div>
  )
}

import { CircleIcon, PlayIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

import type { TimelineEntry, TimelineOrder, TimelineType } from "./types"

const FALLBACK_ICON = CircleIcon

function iconStyle(tone: TimelineType["tone"]) {
  if (tone === undefined) return undefined
  return {
    color: `var(--chart-${tone})`,
    backgroundColor: `color-mix(in oklab, var(--chart-${tone}) 16%, var(--background))`,
    borderColor: `color-mix(in oklab, var(--chart-${tone}) 45%, var(--background))`,
  }
}

const levelClass = {
  debug: "text-muted-foreground",
  info: "text-muted-foreground",
  warning: "font-medium text-foreground",
  error: "font-medium text-destructive",
} as const

/**
 * One timeline entry: type icon, category, level word, message, optional detail
 * and a time that becomes a seek button when `onSeek` is given. `after` dims it,
 * `current` marks the entry the playhead last reached, and an `isError` entry
 * gets the error look and a rule on its older side (below it when newest first).
 */
export function EntryRow({
  entry,
  type,
  time,
  order,
  after = false,
  current = false,
  errorLabel = "This event",
  onSeek,
}: {
  entry: TimelineEntry
  type?: TimelineType
  time: string
  order: TimelineOrder
  after?: boolean
  current?: boolean
  errorLabel?: string
  onSeek?: (time: number) => void
}) {
  const Icon = type?.icon ?? FALLBACK_ICON
  const marked = entry.isError === true
  return (
    <li
      data-mini="entry"
      data-after={after || undefined}
      aria-current={current ? "time" : undefined}
      className={cn(
        "relative flex list-none gap-3 px-3 py-2.5",
        after && "opacity-50",
        marked && (order === "newest" ? "border-b border-destructive" : "border-t border-destructive")
      )}
    >
      <span
        aria-hidden
        style={marked ? undefined : iconStyle(type?.tone)}
        className={cn(
          "relative z-10 mt-0.5 grid size-7 shrink-0 place-items-center rounded-full border bg-background text-muted-foreground",
          marked && "border-destructive text-destructive"
        )}
      >
        <Icon className="size-3.5" />
      </span>
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <span className={cn("truncate font-semibold", marked && "text-destructive")}>{entry.category}</span>
          <span className={cn("shrink-0 text-xs", levelClass[entry.level])}>{entry.level}</span>
          {marked ? (
            <span className="shrink-0 text-xs text-destructive">{errorLabel}</span>
          ) : null}
          <span className="ml-auto shrink-0">
            {onSeek ? (
              <Button
                variant="ghost"
                size="xs"
                aria-label={`Seek to ${time}`}
                title={`Seek to ${time}`}
                onClick={() => onSeek(entry.time)}
                className="-mr-1.5 text-muted-foreground tabular-nums"
              >
                <PlayIcon aria-hidden />
                {time}
              </Button>
            ) : (
              <span className="text-xs text-muted-foreground tabular-nums">{time}</span>
            )}
          </span>
        </div>
        <p className="break-words">{entry.message}</p>
        {entry.detail ? (
          <p className="break-words font-[family-name:var(--mini-font-data)] text-xs text-muted-foreground">
            {entry.detail}
          </p>
        ) : null}
      </div>
    </li>
  )
}

import {
  useEffect,
  useEffectEvent,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
} from "react"
import { useHotkeys } from "react-hotkeys-hook"
import { ArrowDownIcon, ArrowUpIcon, LocateFixedIcon, SearchIcon } from "lucide-react"

import { EmptyState, ErrorState, LoadingState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"

import { EntryRow } from "./entry-row"
import { PlayheadDivider } from "./playhead-divider"
import {
  buildRows,
  entryTypes,
  formatOffset,
  typeFromOptionValue,
  typeLabel,
  typeOptionValue,
} from "./timeline"
import type { TimelineEntry, TimelineOrder, TimelineType } from "./types"

export type EventTimelineProps = {
  entries: TimelineEntry[]
  status?: "loading" | "ready" | "error"
  error?: Error
  onRetry?: () => void
  types?: Record<string, TimelineType>
  defaultOrder?: TimelineOrder
  playhead?: number
  onSeek?: (time: number) => void
  formatTime?: (time: number) => string
  errorLabel?: string
  emptyTitle?: string
  emptyAction?: { label: string; onClick: () => void }
  "aria-label"?: string
}

// type keys are prefixed into option values (see typeOptionValue), so this can never collide with one
const ANY_TYPE = "any"
const FOLLOW_PADDING = 48

/**
 * Time-ordered list of typed entries with search, a type filter and an order
 * control. With a finite `playhead` it dims later entries, draws a divider at the
 * playhead and scrolls to follow it until the user scrolls the divider out of
 * view; `onSeek` turns each time into a seek button. Takes data as props and
 * never reads the store. Keys act when focus is on the page body or inside this
 * block, never while typing in an input.
 */
export function EventTimeline({
  entries,
  status = "ready",
  error,
  onRetry,
  types = {},
  defaultOrder = "newest",
  playhead,
  onSeek,
  formatTime = formatOffset,
  errorLabel = "This event",
  emptyTitle = "No activity yet",
  emptyAction,
  "aria-label": ariaLabel = "Timeline",
}: EventTimelineProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const scrollerRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const programmaticTop = useRef<number | null>(null)

  const [query, setQuery] = useState("")
  const [type, setType] = useState<string | null>(null)
  const [order, setOrder] = useState<TimelineOrder>(defaultOrder)
  const [following, setFollowing] = useState(true)

  const ready = status === "ready"
  const usable = ready && entries.length > 0
  const typeKeys = useMemo(() => entryTypes(entries), [entries])
  const activeType = type !== null && typeKeys.includes(type) ? type : null
  const filtering = query.trim() !== "" || activeType !== null
  const hasPlayhead = playhead !== undefined && Number.isFinite(playhead)

  const rows = useMemo(
    () => (usable ? buildRows(entries, { query, type: activeType, order, playhead }) : []),
    [usable, entries, query, activeType, order, playhead]
  )
  const entryCount = rows.filter((row) => row.kind === "entry").length
  const hasDivider = rows.some((row) => row.kind === "playhead")

  const findDivider = () =>
    scrollerRef.current?.querySelector<HTMLElement>('[data-mini="playhead"]') ?? null

  const reveal = useEffectEvent(() => {
    const scroller = scrollerRef.current
    const divider = findDivider()
    if (!scroller || !divider) return
    const box = divider.getBoundingClientRect()
    const top = box.top - scroller.getBoundingClientRect().top + scroller.scrollTop
    let next = scroller.scrollTop
    if (top < scroller.scrollTop + FOLLOW_PADDING) {
      next = top - FOLLOW_PADDING
    } else if (top + box.height > scroller.scrollTop + scroller.clientHeight - FOLLOW_PADDING) {
      next = top + box.height - scroller.clientHeight + FOLLOW_PADDING
    }
    const before = scroller.scrollTop
    scroller.scrollTop = Math.max(0, next)
    // the scroll event this fires must not read as the user scrolling away
    if (scroller.scrollTop !== before) programmaticTop.current = scroller.scrollTop
  })

  const dividerInView = () => {
    const scroller = scrollerRef.current
    const divider = findDivider()
    if (!scroller || !divider) return false
    const area = scroller.getBoundingClientRect()
    const box = divider.getBoundingClientRect()
    return box.bottom > area.top && box.top < area.bottom
  }

  useEffect(() => {
    if (hasDivider && following) reveal()
  }, [rows, hasDivider, following])

  // a playhead that moves into view by itself ends the detached state, which scroll events alone would miss
  useEffect(() => {
    const scroller = scrollerRef.current
    const divider = findDivider()
    if (!scroller || !divider) return
    const observer = new IntersectionObserver(
      (observed) => {
        if (observed.some((item) => item.isIntersecting)) setFollowing(true)
      },
      { root: scroller }
    )
    observer.observe(divider)
    return () => observer.disconnect()
  }, [rows])

  const onScroll = () => {
    const scroller = scrollerRef.current
    if (!scroller) return
    const own = programmaticTop.current
    programmaticTop.current = null
    if (own !== null && Math.abs(scroller.scrollTop - own) < 2) return
    if (findDivider()) setFollowing(dividerInView())
  }

  // following flips on, and the effect above scrolls
  const jumpToPlayhead = () => setFollowing(true)

  const seek = (time: number) => {
    onSeek?.(time)
    setFollowing(true)
  }

  const inScope = (event: KeyboardEvent) => {
    const target = event.target
    if (target === document.body || target === document.documentElement) return true
    if (!(target instanceof Element) || !rootRef.current?.contains(target)) return false
    // the select trigger has its own type-ahead, which these letters would fight
    return target.closest('[role="combobox"]') === null
  }
  useHotkeys(
    "slash",
    (event) => {
      if (!inScope(event)) return
      event.preventDefault()
      inputRef.current?.focus()
    },
    { enabled: usable }
  )
  useHotkeys(
    "o",
    (event) => {
      if (!inScope(event)) return
      event.preventDefault()
      setOrder((current) => (current === "newest" ? "oldest" : "newest"))
    },
    { enabled: usable }
  )
  useHotkeys(
    "p",
    (event) => {
      if (!inScope(event)) return
      event.preventDefault()
      jumpToPlayhead()
    },
    { enabled: usable && hasDivider }
  )

  const onSearchKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.key !== "Escape") return
    event.preventDefault()
    if (query) setQuery("")
    else {
      event.currentTarget.blur()
      scrollerRef.current?.focus({ preventScroll: true })
    }
  }

  const clearFilters = () => {
    setQuery("")
    setType(null)
  }

  const count = filtering
    ? `${entryCount} of ${entries.length} entries`
    : `${entries.length} ${entries.length === 1 ? "entry" : "entries"}`

  let body
  if (status === "loading") {
    body = <LoadingState label="Loading timeline" />
  } else if (status === "error") {
    body = <ErrorState error={error ?? new Error("Unknown error")} onRetry={onRetry} />
  } else if (entries.length === 0) {
    body = (
      <EmptyState
        title={emptyTitle}
        description="Entries will show up here in time order."
        action={
          emptyAction ? (
            <Button variant="outline" size="sm" onClick={emptyAction.onClick}>
              {emptyAction.label}
            </Button>
          ) : undefined
        }
      />
    )
  } else if (rows.length === 0) {
    const parts = [
      query.trim() ? `"${query.trim()}"` : null,
      activeType !== null ? typeLabel(activeType, types[activeType]?.label) : null,
    ].filter((part) => part !== null)
    body = (
      <EmptyState
        title={`No entries match ${parts.join(" in ")}`}
        description="Try a different word or type, or clear the filters."
        action={
          <Button variant="outline" size="sm" onClick={clearFilters}>
            Clear filters
          </Button>
        }
      />
    )
  } else {
    body = (
      <ol
        className="relative m-0 p-0 before:absolute before:top-6 before:bottom-6 before:left-[26px] before:w-px before:bg-border"
      >
        {rows.map((row) =>
          row.kind === "playhead" ? (
            <PlayheadDivider key="playhead" time={formatTime(row.time)} />
          ) : (
            <EntryRow
              key={row.entry.id}
              entry={row.entry}
              type={types[row.entry.type]}
              time={formatTime(row.entry.time)}
              order={order}
              after={row.after}
              current={row.current}
              errorLabel={errorLabel}
              onSeek={onSeek ? seek : undefined}
            />
          )
        )}
      </ol>
    )
  }

  const OrderIcon = order === "newest" ? ArrowDownIcon : ArrowUpIcon

  return (
    <div ref={rootRef} className="flex h-full min-h-0 flex-col bg-background text-sm">
      <div className="flex shrink-0 flex-wrap items-center gap-2 border-b px-3 py-2">
        <div className="relative min-w-40 max-w-72 flex-1">
          <SearchIcon
            aria-hidden
            className="pointer-events-none absolute top-1/2 left-2.5 size-3.5 -translate-y-1/2 text-muted-foreground"
          />
          <Input
            ref={inputRef}
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            onKeyDown={onSearchKeyDown}
            disabled={!usable}
            placeholder="Search entries (press /)"
            aria-label="Search entries"
            className="h-8 pl-8"
          />
        </div>
        <Select
          value={activeType === null ? ANY_TYPE : typeOptionValue(activeType)}
          onValueChange={(value) => setType(typeFromOptionValue(value))}
          disabled={!usable}
        >
          <SelectTrigger size="sm" aria-label="Filter by type" className="w-36">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value={ANY_TYPE}>Any type</SelectItem>
            {typeKeys.map((key) => (
              <SelectItem key={key} value={typeOptionValue(key)}>
                {typeLabel(key, types[key]?.label)}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Button
          variant="outline"
          size="sm"
          disabled={!usable}
          title="Switch order (o)"
          onClick={() => setOrder(order === "newest" ? "oldest" : "newest")}
        >
          <OrderIcon aria-hidden />
          {order === "newest" ? "Newest first" : "Oldest first"}
        </Button>
        <span aria-live="polite" className="ml-auto shrink-0 text-xs text-muted-foreground tabular-nums">
          {usable ? count : ""}
        </span>
      </div>
      <div className="relative min-h-0 flex-1">
        <div
          ref={scrollerRef}
          role="region"
          tabIndex={0}
          aria-label={ariaLabel}
          onScroll={onScroll}
          className="h-full overflow-y-auto outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50"
        >
          {body}
        </div>
        {hasPlayhead && hasDivider && !following ? (
          <Button
            size="sm"
            variant="secondary"
            onClick={jumpToPlayhead}
            className="absolute bottom-3 left-1/2 -translate-x-1/2 shadow-md"
          >
            <LocateFixedIcon aria-hidden />
            Jump to playhead
          </Button>
        ) : null}
      </div>
    </div>
  )
}

import { cn } from "@/lib/utils"

/** Full-width line marking the playhead between the entries it has reached and those after it. */
export function PlayheadDivider({ time, className }: { time: string; className?: string }) {
  return (
    <li role="presentation" data-mini="playhead" className={cn("list-none", className)}>
      <div
        role="separator"
        aria-label={`Playhead at ${time}`}
        className="flex items-center gap-2 px-3 py-1.5"
      >
        <span aria-hidden className="h-px flex-1 bg-primary" />
        <span className="flex items-center gap-1.5 rounded-full bg-primary px-2 py-0.5 text-xs font-medium text-primary-foreground tabular-nums">
          <span aria-hidden className="size-1.5 rounded-full bg-primary-foreground" />
          Playhead {time}
        </span>
        <span aria-hidden className="h-px flex-1 bg-primary" />
      </div>
    </li>
  )
}

import type { TimelineEntry, TimelineFilter, TimelineOrder, TimelineRow } from "./types"

/** Distinct entry types in first-seen order, for the type filter. */
export function entryTypes(entries: TimelineEntry[]): string[] {
  return [...new Set(entries.map((entry) => entry.type))]
}

const TYPE_OPTION_PREFIX = "type:"

/** The type select's item value for a type key; never empty, so a key of "" stays selectable. */
export function typeOptionValue(key: string): string {
  return TYPE_OPTION_PREFIX + key
}

/** The type key behind a value made by `typeOptionValue`, or null for any other value. */
export function typeFromOptionValue(value: string): string | null {
  return value.startsWith(TYPE_OPTION_PREFIX) ? value.slice(TYPE_OPTION_PREFIX.length) : null
}

/** The label to show for a type key: the configured label, else the key, else "No type" for an empty key. */
export function typeLabel(key: string, label?: string): string {
  return label || key || "No type"
}

/** Entries matching the type (when given) and containing the query in category, message, detail or type. */
export function filterEntries(entries: TimelineEntry[], { query, type }: TimelineFilter): TimelineEntry[] {
  const needle = query.trim().toLowerCase()
  return entries.filter((entry) => {
    if (type !== null && entry.type !== type) return false
    if (!needle) return true
    return [entry.category, entry.message, entry.detail ?? "", entry.type].some((text) =>
      text.toLowerCase().includes(needle)
    )
  })
}

/** A sorted copy. Entries with equal times keep their input order oldest first, and newest first is the exact mirror. */
export function sortEntries(entries: TimelineEntry[], order: TimelineOrder): TimelineEntry[] {
  const oldest = entries
    .map((entry, index) => ({ entry, index }))
    .sort((a, b) => a.entry.time - b.entry.time || a.index - b.index)
    .map(({ entry }) => entry)
  return order === "newest" ? oldest.reverse() : oldest
}

/**
 * The rows to draw: filtered, ordered entries and, when `playhead` is a finite
 * number, one divider between the entries the playhead has reached (time at or
 * before it) and those after it. Entries after the playhead are flagged `after`;
 * the last reached entry among the filtered ones is `current`.
 */
export function buildRows(
  entries: TimelineEntry[],
  options: TimelineFilter & { order: TimelineOrder; playhead?: number }
): TimelineRow[] {
  const { order, playhead } = options
  const ordered = sortEntries(filterEntries(entries, options), order)
  if (ordered.length === 0) return []
  if (playhead === undefined || !Number.isFinite(playhead)) {
    return ordered.map((entry) => ({ kind: "entry", entry, after: false, current: false }))
  }

  const reached = (entry: TimelineEntry) => entry.time <= playhead
  const reachedInOrder = ordered.filter(reached)
  const currentId = (order === "newest" ? reachedInOrder[0] : reachedInOrder.at(-1))?.id
  const rows: TimelineRow[] = ordered.map((entry) => ({
    kind: "entry",
    entry,
    after: !reached(entry),
    current: entry.id === currentId,
  }))

  const afterCount = ordered.filter((entry) => !reached(entry)).length
  const dividerAt = order === "newest" ? afterCount : ordered.length - afterCount
  rows.splice(dividerAt, 0, { kind: "playhead", time: playhead })
  return rows
}

/** Milliseconds as mm:ss, or h:mm:ss from one hour; negative and non-finite values read as zero. */
export function formatOffset(ms: number): string {
  const total = Number.isFinite(ms) && ms > 0 ? Math.floor(ms / 1000) : 0
  const hours = Math.floor(total / 3600)
  const minutes = Math.floor((total % 3600) / 60)
  const seconds = total % 60
  const pad = (n: number) => String(n).padStart(2, "0")
  return hours > 0 ? `${hours}:${pad(minutes)}:${pad(seconds)}` : `${pad(minutes)}:${pad(seconds)}`
}

import type { LucideIcon } from "lucide-react"

export type TimelineLevel = "debug" | "info" | "warning" | "error"

export type TimelineOrder = "newest" | "oldest"

export type TimelineEntry = {
  id: string
  /** Milliseconds. Entries and the playhead share one scale; the host decides what zero means. */
  time: number
  /** Key into the `types` prop; also what the type filter lists. */
  type: string
  category: string
  level: TimelineLevel
  message: string
  /** Optional second line in the data font, such as a path or selector. */
  detail?: string
  /** Marks the failing moment: it gets the error look and a rule on its older side. */
  isError?: boolean
}

export type TimelineType = {
  label: string
  icon: LucideIcon
  /** Picks `--chart-<tone>` for the icon circle; plain muted when omitted. */
  tone?: 1 | 2 | 3 | 4 | 5
}

export type TimelineFilter = { query: string; type: string | null }

export type TimelineRow =
  | { kind: "entry"; entry: TimelineEntry; after: boolean; current: boolean }
  | { kind: "playhead"; time: number }
